import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// Stand-in for a real database. Swap these two functions for your data layer;
// the caching and invalidation around them stays the same.
const posts: Post[] = []

export async function getPosts(): Promise<Post[]> {
  'use cache'
  // Tag every cache entry produced here so a single `updateTag('posts')` in a
  // Server Action expires all of them.
  cacheTag('posts')

  return posts.toReversed()
}

export async function insertPost(data: {
  title: string
  content: string
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title: data.title,
    content: data.content,
    createdAt: new Date().toISOString(),
  }
  posts.push(post)
  return post
}

