'use server'

import { updateTag } from 'next/cache'
import { insertPost } from './posts'

export type CreatePostResult = { error: string } | { error: null; id: string }

export async function createPost(
  formData: FormData
): Promise<CreatePostResult> {
  const title = String(formData.get('title') ?? '').trim()
  const content = String(formData.get('content') ?? '').trim()

  if (!title) {
    return { error: 'Title is required.' }
  }

  const post = await insertPost({ title, content })

  // `updateTag` expires the "posts" cache entries immediately, so the next read
  // must recompute and wait for fresh data — no stale content is ever served.
  //
  // Deliberately NOT `revalidateTag('posts', ...)`: that marks entries stale and
  // keeps serving the old value while refreshing in the background, which would
  // show this user a posts list without the post they just created.
  updateTag('posts')

  return { error: null, id: post.id }
}

